async function quickLoginSampleUser(userId) {
  const user = sampleUsers.find(u => u.id === userId);
  if (!user) return;
  state.loginRole = user.role;
  toast(tr("Signing in as") + " " + user.name + " (" + tr(user.role) + ")...");

  // Autofill form inputs if available
  const phoneInput = document.querySelector('input[name="phone"]');
  const passInput = document.querySelector('input[name="password"]');
  if (phoneInput) phoneInput.value = user.phone;
  if (passInput) passInput.value = user.password;

  try {
    const formData = new FormData();
    formData.append("phone", user.phone);
    formData.append("password", user.password);
    const result = await authRequest("/api/auth/login", formData);
    const u = result.user;
    state.user = u.name;
    state.role = u.role;
    state.signed = true;
    state.serverUserId = u.id;
    state.lang = u.language === "en" ? "en" : "am";
    save();
    render(u.role === "admin" ? "admin" : u.role === "agent" ? "agent-dashboard" : "project");
    toast(tr("Signed in to your server account.") + " — " + u.name);
  } catch (err) {
    console.warn("Server auth failed, activating local demo session:", err);
    // Graceful offline fallback
    state.user = user.name;
    state.role = user.role;
    state.signed = true;
    state.serverUserId = user.id;
    save();
    render(user.role === "admin" ? "admin" : user.role === "agent" ? "agent-dashboard" : "project");
    toast(tr("Signed in as") + " " + user.name + " (" + tr(user.role) + ")");
  }
}

function autofillLoginForm(userId) {
  const user = sampleUsers.find(u => u.id === userId);
  if (!user) return;
  const phoneInput = document.querySelector('input[name="phone"]');
  const passInput = document.querySelector('input[name="password"]');
  if (phoneInput) {
    phoneInput.value = user.phone;
    phoneInput.classList.add("highlight-field");
  }
  if (passInput) {
    passInput.value = user.password;
    passInput.classList.add("highlight-field");
  }
  toast(tr("Auto-filled") + " " + user.name + " (" + user.phone + ")");
}

