  const nameInput = document.querySelector('#registerForm input[name="name"]');
  const phoneInput = document.querySelector('#registerForm input[name="phone"]');
  const passInput = document.querySelector('#registerForm input[name="password"]');
  const termsBox = document.querySelector('#registerForm input[name="terms"]');
  const consentBox = document.querySelector('#registerForm input[name="consent"]');

  if (nameInput) nameInput.value = item.name;
