function review(){
  state.title="Review queues";
  const reviewItems=state.role==="admin"?state.items:state.items.filter(x=>x.agentCode===(state.agentCode||demoAgentCode)&&x.status!=="Approved");
  const visible=state.reviewTab&&state.reviewTab!=="All"?reviewItems.filter(x=>state.reviewTab==="Audio"?(x.type==="Audio"||!!x.recordingFileName):state.reviewTab==="Transcripts"?(x.type==="Transcription"||!!x.translation):(x.type==="Translation"||!!x.translation)):reviewItems;
  return heading("QUALITY · ADMIN","Review queues","Review audio, transcripts, and translations. Decisions are demo-only.")+
    '<div class="admin-tabs">'+["All","Audio","Transcripts","Translations"].map(x=>'<button class="filter-chip '+(state.reviewTab===x?"selected":"")+'" data-filter="'+x+'">'+tr(x)+'</button>').join("")+'</div><div class="review-grid">'+
    visible.map(x=>{
      const actions=state.role==="admin"?'<div class="field"><label>'+tr("Correction notes")+'</label><input data-note="'+esc(x.id)+'" placeholder="'+tr("Correction notes")+'"></div><div class="field"><label>'+tr("Rejection reason")+'</label><input data-reason="'+esc(x.id)+'" placeholder="'+tr("Rejection reason")+'"></div><div class="review-actions"><button class="primary-button" data-review="Approved" data-id="'+esc(x.id)+'">'+tr("Approve")+'</button><button class="secondary-button" data-review="Returned" data-id="'+esc(x.id)+'">'+tr("Return with notes")+'</button><button class="danger-button" data-review="Rejected" data-id="'+esc(x.id)+'">'+tr("Reject")+'</button><button type="button" class="danger-button" data-action="admin-delete-item" data-id="'+esc(x.id)+'">'+tr("Delete record")+'</button></div>':'<p class="demo-note">'+tr("Agent review actions are shown in the contributor work folder.")+'</p>';
      const packageLink=state.role==="admin"&&reviewPackageUrls.has(x.id)?'<audio controls preload="metadata" src="'+reviewPackageUrls.get(x.id).audioUrl+'"></audio><p><a href="'+reviewPackageUrls.get(x.id).packageUrl+'" download="ELDF-review-'+esc(x.id)+'.json">'+tr("Download complete review package")+'</a></p>':'';
      return '<article class="review-card"><div class="panel-heading"><div><h3>'+esc(x.id)+' · '+tr(x.language)+'</h3><p>'+esc(x.title)+' · '+esc(x.type)+'</p></div><span class="status-pill '+statusClass(x.status)+'">'+tr(x.status)+'</span></div><div class="transcript-box"><b>'+tr("Transcript")+'</b><br>'+esc(x.text||"Demo recording · no audio file saved")+(x.translation?'<hr><b>'+tr("Translation")+'</b><br>'+esc(x.translation):"")+'</div>'+(x.participants?'<div class="review-participants"><b>'+tr("Participants")+'</b>'+x.participants.map(p=>'<p>'+esc(p.speakerId)+' · '+esc(p.preferredLanguage||"")+' · '+esc(p.region||"")+' · '+esc(p.dialect||"")+' · '+esc(p.ageRange||"")+' · '+esc(p.gender||"")+'</p>').join("")+'</div>':"")+packageLink+'<div class="revision-list"><b>'+tr("Revision history")+'</b>'+x.history.map(h=>'<small>'+tr(h.status)+' · '+esc(h.by)+' · '+esc(h.date)+(h.note?" · "+esc(h.note):"")+'</small>').join("")+'</div>'+actions+'</article>';
    }).join("")+'</div>';
}
