function formatTime(s){const n=Number(s);const total=Number.isFinite(n)?Math.max(0,Math.floor(n)):0;return String(Math.floor(total/3600)).padStart(2,"0")+":"+String(Math.floor(total/60)%60).padStart(2,"0")+":"+String(total%60).padStart(2,"0")}
function stopMeter(){if(meterTimer){cancelAnimationFrame(meterTimer);meterTimer=0}if(meterSource){try{meterSource.disconnect()}catch{}meterSource=null}if(audioCtx){audioCtx.close().catch(()=>{});audioCtx=null}const meter=document.getElementById("inputLevelMeter")||document.querySelector(".meter i"),label=document.getElementById("inputLevelValue")||document.querySelector(".level-value"),bar=document.querySelector(".studio-meter")||document.querySelector(".meter"),wave=document.querySelectorAll("#studioWave i");if(meter)meter.style.width="0%";if(label)label.textContent="0%";if(bar)bar.setAttribute("aria-valuenow","0");wave.forEach(x=>x.style.height="0px")}
async function meterStart(stream){stopMeter();const signal=document.getElementById("signalStatus");try{const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)throw new Error("unavailable");audioCtx=new AudioContextClass();if(audioCtx.state==="suspended")await audioCtx.resume();meterSource=audioCtx.createMediaStreamSource(stream);const analyser=audioCtx.createAnalyser();analyser.fftSize=256;meterSource.connect(analyser);const data=new Uint8Array(analyser.fftSize);let lastSignal=0;const sample=()=>{if(!audioCtx||!meterSource)return;analyser.getByteTimeDomainData(data);let sum=0;for(const v of data){const x=(v-128)/128;sum+=x*x}const rms=Math.sqrt(sum/data.length),pct=Math.max(0,Math.min(100,Math.round(rms*350))),active=rms>.006;if(active)lastSignal=Date.now();const meter=document.getElementById("inputLevelMeter")||document.querySelector(".meter i"),label=document.getElementById("inputLevelValue")||document.querySelector(".level-value"),bar=document.querySelector(".studio-meter")||document.querySelector(".meter"),wave=document.querySelectorAll("#studioWave i");if(meter)meter.style.width=pct+"%";if(label)label.textContent=pct+"%";if(bar)bar.setAttribute("aria-valuenow",String(pct));wave.forEach((x,i)=>x.style.height=(active?Math.max(1,Math.min(45,Math.abs(data[(i*2)%data.length]-128)*.55)):0)+"px");const signalText=active||Date.now()-lastSignal<900?"Audio signal detected":"No audio signal detected";if(signal)signal.textContent=tr(signalText);else if(state.view==="prepare"){const report=document.getElementById("qualityResult");if(report)report.textContent=tr(signalText)}meterTimer=requestAnimationFrame(sample)};sample()}catch{if(signal)signal.textContent=tr("Live microphone level unavailable");else if(state.view==="prepare"){const report=document.getElementById("qualityResult");if(report)report.textContent=tr("Live microphone level unavailable")}stopMeter()}}
function releaseMicrophone(stream=mic){if(stream)stream.getTracks().forEach(track=>track.stop());if(stream===mic)mic=null;stopMeter()}
function audioExtension(type=""){if(type.includes("ogg"))return "ogg";if(type.includes("mp4"))return "m4a";if(type.includes("wav"))return "wav";return "webm"}
function recordingErrorKey(error){if(!window.isSecureContext&&location.hostname!=="localhost"&&location.hostname!=="127.0.0.1")return "Microphone recording is not available on this page. Open the site on localhost or HTTPS.";if(error?.name==="NotSupportedError")return "Your browser does not support microphone recording. Try a recent version of Chrome, Edge, or Firefox.";if(error?.name==="NotAllowedError"||error?.name==="PermissionDeniedError"||error?.name==="SecurityError")return "Microphone permission was denied. Allow microphone access in your browser settings and try again.";if(["NotFoundError","DevicesNotFoundError"].includes(error?.name))return "No microphone was found. Connect a microphone and try again.";if(error?.name==="NotReadableError"||error?.name==="AbortError")return "The microphone is busy or unavailable. Close other apps using it and try again.";return "Recording failed. Please try again."}
