function selectedConversationPromptIndices(){const valid=Array.isArray(state.selectedConversationPrompts)?state.selectedConversationPrompts.filter(index=>Number.isInteger(index)&&index>=0&&index<conversationPrompts.length):[];return valid.length?valid:[0,1]}
let conversationTopicCursor=0,conversationTopicStartedAt=0;
function topicIntervalSeconds(){return Math.max(1,Number(state.topicIntervalMinutes)||5)*60}
function sessionMaxSeconds(){return Math.min(3600,Math.max(60,Number(state.adminConfig?.maxRecordingMinutes)||60)*60)}
function allowedAudioExtensions(){return String(state.adminConfig?.allowedTypes||"WAV, MP3, M4A, OGG").toLowerCase().split(/[,\s]+/).map(x=>x.replace(/^\./,"")).filter(x=>["wav","mp3","m4a","ogg"].includes(x))}
function currentConversationPromptIndex(seconds=recordingElapsed()){const selected=selectedConversationPromptIndices(),steps=Math.floor(Math.max(0,seconds-conversationTopicStartedAt)/topicIntervalSeconds());return selected[(conversationTopicCursor+steps)%selected.length]}
function nextConversationTopic(){if(!["recording","paused"].includes(recordingState))return;const selected=selectedConversationPromptIndices(),seconds=Math.min(sessionMaxSeconds(),Math.max(0,Math.floor(recordingElapsed()))),steps=Math.floor(Math.max(0,seconds-conversationTopicStartedAt)/topicIntervalSeconds()),current=(conversationTopicCursor+steps)%selected.length;conversationTopicCursor=(current+1)%selected.length;conversationTopicStartedAt=seconds;updateConversationGuide()}
function updateConversationGuide(){const active=["starting","recording","paused","finalizing","completed"].includes(recordingState),seconds=active?Math.min(sessionMaxSeconds(),Math.max(0,Math.floor(recordingElapsed()))):0,selected=selectedConversationPromptIndices(),interval=topicIntervalSeconds(),steps=Math.floor(Math.max(0,seconds-conversationTopicStartedAt)/interval),index=active?currentConversationPromptIndex(Math.min(seconds,Math.max(0,sessionMaxSeconds()-1))):selected[0],prompt=conversationPrompts[index],slot=active?steps+1:1,segmentStart=active?conversationTopicStartedAt+steps*interval:0,title=document.getElementById("sessionPromptTitle"),body=document.getElementById("sessionPromptText"),segment=document.getElementById("sessionSegment"),progress=document.getElementById("sessionProgress"),category=document.getElementById("sessionCategory");if(title)title.textContent=state.lang==="am"?prompt.am:prompt.en;if(body)body.textContent=tr("Keep the conversation in the selected project language. Take turns and speak naturally.");if(category)category.textContent=(prompt.category?tr(prompt.category)+" · "+prompt.range:tr("Conversation starter"))+" · "+tr("Topic")+" "+(selected.indexOf(index)+1)+" / "+selected.length;if(segment)segment.textContent=slot+" · "+formatTime(segmentStart)+"–"+formatTime(Math.min(segmentStart+interval,sessionMaxSeconds()));if(progress)progress.style.width=Math.min(100,seconds/sessionMaxSeconds()*100)+"%";const next=document.getElementById("nextConversationTopic");if(next)next.disabled=recordingState!=="recording"}
function startSessionClock(){clearInterval(clock);clock=setInterval(()=>{const seconds=Math.floor(recordingElapsed()),face=document.getElementById("recordClock");if(face)face.textContent=formatTime(seconds);updateRecordingControls();updateConversationGuide();if(seconds>=sessionMaxSeconds())stopCapture()},1000);updateConversationGuide()}
function recordingElapsed(){return elapsed+(recordingState==="recording"?Math.max(0,(Date.now()-recordStarted)/1000):0)}
function updateRecordingControls(message){const status=document.getElementById("recordStatus"),statusLabel=document.getElementById("recordStatusLabel"),clockFace=document.getElementById("recordClock"),player=document.getElementById("playback"),download=document.getElementById("downloadAudio"),report=document.getElementById("qualityReport");if(status){const keys={starting:"Starting...",recording:"Recording",paused:"Paused",finalizing:"Processing",completed:"Completed",error:"Recording error"};status.dataset.state=recordingState;status.className="record-status"+(recordingState==="recording"?" is-recording":recordingState==="paused"?" is-paused":recordingState==="finalizing"?" is-processing":recordingState==="completed"?" is-completed":"")+(recordingState==="error"?" is-error":"");if(statusLabel)statusLabel.textContent=tr(message||recordingNotice||keys[recordingState]||"Ready")}if(clockFace)clockFace.textContent=formatTime(Math.floor(recordingElapsed()));if(player){player.hidden=!audioBlob||!audioUrl;if(audioUrl&&player.src!==audioUrl)player.src=audioUrl}if(download){download.hidden=state.role!=="admin"||!audioBlob||!audioUrl;if(audioUrl){download.href=audioUrl;download.download="ethiopian-language-recording."+audioExtension(audioBlob?.type)}}if(report&&recordingNotice)report.textContent=tr(recordingNotice);else if(report&&recordingState==="completed"&&audioBlob&&!state.audioMeta?.grade&&!state.audioMeta?.analyzing)report.textContent=tr("Recording complete. Listen to or download your audio.");const panel=document.getElementById("playerPanel"),playButton=document.getElementById("playbackToggle");if(panel)panel.hidden=!audioBlob||!audioUrl;if(playButton){playButton.disabled=!audioBlob||!audioUrl;playButton.textContent=tr(player&& !player.paused?"Pause Playback":"Play Playback")}if(player){player.onplay=()=>{const b=document.getElementById("playbackToggle");if(b)b.textContent=tr("Pause Playback")};player.onpause=()=>{const b=document.getElementById("playbackToggle");if(b)b.textContent=tr("Play Playback")};player.onended=()=>{const b=document.getElementById("playbackToggle");if(b)b.textContent=tr("Play Playback")}}const focus=document.getElementById("focusModeToggle");if(focus){focus.textContent=tr(document.body.classList.contains("recording-focus")?"Exit Focus Mode":"Focus Mode");focus.setAttribute("aria-pressed",String(document.body.classList.contains("recording-focus")))}const busy=startingCapture||["starting","recording","paused","finalizing"].includes(recordingState);const startButton=document.getElementById("record-start"),pauseButton=document.getElementById("record-pause"),resumeButton=document.getElementById("record-resume"),stopButton=document.getElementById("record-stop"),resetButton=document.getElementById("record-reset"),deleteButton=document.getElementById("record-delete"),fileInput=document.getElementById("audioFile");if(startButton)startButton.disabled=busy||!!audioBlob;if(pauseButton)pauseButton.disabled=recordingState!=="recording";if(resumeButton)resumeButton.disabled=recordingState!=="paused";if(stopButton)stopButton.disabled=!(["recording","paused"].includes(recordingState)&&recordingElapsed()>=1800);const cancelButton=document.getElementById("record-cancel");if(cancelButton)cancelButton.disabled=!(recorder&&["recording","paused"].includes(recordingState));if(resetButton)resetButton.disabled=busy;if(deleteButton)deleteButton.disabled=busy||!audioBlob;if(fileInput)fileInput.disabled=busy;const acceptButton=document.querySelector("[data-action=\"accept-audio\"]");if(acceptButton)acceptButton.disabled=busy||!audioBlob||!!state.audioMeta?.analyzing||!state.audioMeta?.grade;updateConversationGuide()}
