function pauseCapture(){if(!recorder||recorder.state!=="recording"||recordingState!=="recording")return;elapsed+=Math.max(0,(Date.now()-recordStarted)/1000);try{recorder.pause();recordingState="paused";clearInterval(clock);clock=null;stopMeter();updateRecordingControls("Paused")}catch(error){recordingNotice=recordingErrorKey(error);updateRecordingControls(recordingNotice)}}
