function qualityText(value){if(state.lang!=="am")return value;const am={"Analyzing audio…":"ድምፁን በመመርመር ላይ…","Rating":"ደረጃ","Pass":"ያለፈ","Review":"እንደገና ይገምግሙ","Reject":"ውድቅ","File format":"የፋይል ቅርጸት","Audio is almost silent. Check the microphone and record again.":"ድምፁ ጸጥ ብሏል። ማይክሮፎኑን ይፈትሹና እንደገና ይቅረጹ።","Clipping is very high. Lower the microphone level and record again.":"ድምፅ በጣም ተቆርጧል። የማይክሮፎኑን ደረጃ ዝቅ አድርገው እንደገና ይቅረጹ።","Possible clipping detected.":"የድምፅ መቆራረጥ ሊኖር ይችላል።","Speech level looks low.":"የንግግሩ ድምፅ ዝቅተኛ ይመስላል።","Possible background noise detected.":"የጀርባ ድምፅ ሊኖር ይችላል።","Sample rate is below 16 kHz; some speech services recommend at least 16 kHz.":"የናሙና ፍጥነቱ ከ16 kHz በታች ነው፤ አንዳንድ የንግግር አገልግሎቶች ቢያንስ 16 kHz ይመክራሉ።","This file has multiple channels; some speech services prefer mono.":"ይህ ፋይል ብዙ ቻናሎች አሉት፤ አንዳንድ የንግግር አገልግሎቶች mono ይመርጣሉ።","This is a compressed audio format. Keep a lossless master when your project requires one.":"ይህ የተጨመቀ የድምፅ ፋይል ነው። ፕሮጀክቱ ከፈለገ የመጀመሪያውን ያልተጨመቀ ቅጂ ይጠብቁ።","Sample peak":"የናሙና ከፍተኛ ደረጃ","RMS level":"አማካይ የድምፅ ደረጃ","Clipped samples":"የተቆረጡ ናሙናዎች","Sample rate":"የናሙና ፍጥነት","Channels":"የድምፅ ቻናሎች","Estimated quiet-window level":"የጸጥታ ጊዜ የድምፅ ግምት","This is a screening estimate, not an official acceptance decision or certification. Peak is sample peak, not ITU true peak. Google’s recommendations are not a universal standard.":"ይህ የመጀመሪያ ግምገማ ነው፤ ይፋዊ የተቀባይነት ውሳኔ ወይም ማረጋገጫ አይደለም። የሚታየው የናሙና ከፍተኛ ደረጃ ነው፣ የITU true peak አይደለም። የGoogle ምክሮች ሁሉንም የሚያስገድድ መስፈርት አይደሉም።","For safety, browser cleanup is limited to audio up to 10 minutes.":"ለደህንነት የአሳሽ የድምፅ ማጽዳት እስከ 10 ደቂቃ ድምፅ ብቻ ይሰራል።","For safety, browser cleanup is limited to audio up to 2 minutes.":"ለደህንነት የአሳሽ ማጽዳት እስከ 2 ደቂቃ ድምፅ ብቻ ይሰራል።","Long recordings need human review.":"ረጅም ቀረጻዎች በሰው ግምገማ ያስፈልጋቸዋል።","Full automatic analysis is limited to 10 minutes to protect browser memory.":"የአሳሽ ማህደረ ትውስታን ለመጠበቅ ሙሉ ራስ-ሰር ግምገማ እስከ 10 ደቂቃ ብቻ ነው።","Audio could not be measured in this browser. Listen to it and request a human review.":"ድምፁን በዚህ አሳሽ መለካት አልተቻለም። ያዳምጡትና ሰው እንዲገመግመው ይጠይቁ።","Metadata or audio decoding was unavailable.":"የድምፅ መረጃው ወይም ዲኮዲንጉ አልተገኘም።","Creating a cleaned copy…":"የተጣራ ቅጂ በመፍጠር ላይ…","Make a clarity-enhanced copy":"የድምፅ ግልጽነትን የሚያሻሽል ቅጂ ፍጠር","Download enhanced WAV copy":"የተሻሻለውን WAV ቅጂ አውርድ","No major signal issues detected.":"የድምፅ ምልክቱ ላይ ከባድ ችግር አልተገኘም።","Cleaned WAV copy ready. The original is unchanged.":"የተጣራ WAV ቅጂ ዝግጁ ነው። ዋናው ድምፅ አልተቀየረም።","Could not process this audio. The original recording is unchanged.":"ይህን ድምፅ ማስተካከል አልተቻለም። ዋናው ቀረጻ አልተቀየረም።","Wait for the audio quality check to finish.":"የድምፅ ጥራት ምርመራው እስኪጨርስ ይጠብቁ።","This recording did not pass the basic quality screen. Please record it again.":"ይህ ቀረጻ መሠረታዊውን የጥራት ምርመራ አላለፈም። እንደገና ይቅረጹ።","Original audio stays unchanged. Optional speech-focused copy uses a low-frequency filter and gentle compression; it is not AI noise removal.":"ዋናው ድምፅ አይቀየርም። አማራጭ ቅጂው ዝቅተኛ ድግግሞሽ ማጣሪያና ቀላል የድምፅ መጨፍለቅ ይጠቀማል፤ በAI የጀርባ ድምፅ ማስወገድ አይደለም።"};return am[value]||tr(value)}
function audioProcessingApiBase(){return window.ELDF_AUDIO_API_BASE||((location.hostname==="localhost"||location.hostname==="127.0.0.1")?"http://localhost:8001":location.origin)}
async function processAudioWithServer(blob,filename){const form=new FormData();form.append("file",blob,filename||"recording.wav");let response;try{response=await fetch(audioProcessingApiBase()+"/api/audio/process",{method:"POST",body:form})}catch(error){throw new Error("audio-service-unavailable")}if(!response.ok){let message="Audio processing failed.";try{const data=await response.json();message=data.detail||message}catch{}throw new Error(message)}const output=await response.blob();if(output.type!=="audio/wav"||output.size<44)throw new Error("The processing service returned an invalid WAV file.");return{blob:output,duration:Number(response.headers.get("X-Audio-Duration"))||0,trimmed:response.headers.get("X-Audio-Trimmed")==="true"}}
async function processDatasetAudio(blob,filename){try{return await processAudioWithServer(blob,filename)}catch(error){if(!String(error.message).startsWith("Could not decode this audio file."))throw error;const browserWav=await prepareDatasetWav(blob);const wavName=(filename||"recording").replace(/\.[^.]+$/,".wav");return processAudioWithServer(browserWav,wavName)}}
async function upload(file){if(!file)return;let ext=file.name.split(".").pop().toLowerCase();if(!allowedAudioExtensions().includes(ext)){toast("Unsupported format. Choose WAV, MP3, M4A, or OGG.");return}const maxUploadMb=Math.max(1,Number(state.adminConfig?.maxUploadMb)||25);if(file.size>maxUploadMb*1024*1024){toast("File is larger than "+maxUploadMb+" MB.");return}if(audioUrl)URL.revokeObjectURL(audioUrl);if(window.cleanedAudioUrl){URL.revokeObjectURL(window.cleanedAudioUrl);window.cleanedAudioUrl=null}window.cleanedAudioBlob=null;audioBlob=null;recordingState="finalizing";recordingNotice="Preparing audio with noise reduction…";updateRecordingControls("Processing");try{const result=await processDatasetAudio(file,file.name);audioBlob=result.blob;window.originalAudioBlob=file;audioUrl=URL.createObjectURL(audioBlob);recordingState="completed";recordingNotice="Audio processed: noise reduced, edge silence trimmed, converted to 48 kHz mono WAV, and peak normalized to -3 dBFS.";state.audioMeta={duration:result.duration,size:audioBlob.size,type:audioBlob.type,normalizedPeakDb:-3,sampleRate:48000,channels:1,trimmed:result.trimmed,noiseReduced:true};save();updateRecordingControls();await analyze(audioBlob,"main");recordingNotice=""}catch(error){audioBlob=file;window.originalAudioBlob=file;audioUrl=URL.createObjectURL(file);recordingState="completed";recordingNotice=error.message==="audio-service-unavailable"?"Audio processing service is unavailable. Start the Python audio service, then choose this file again.":error.message;state.audioMeta={size:file.size,type:file.type,processingWarning:true};save();updateRecordingControls(recordingNotice);await analyze(file,"main")}}
function downloadTranscript(){const text=document.getElementById("transcriptText")?.value?.trim()||"";if(!text){toast("Write a transcript before downloading.");return}const note=new Blob([text+"\n"],{type:"text/plain;charset=utf-8"}),url=URL.createObjectURL(note),a=document.createElement("a");a.href=url;a.download="ethiopian-language-transcript.txt";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Transcript note downloaded.")}
