  for(let i=0;i<samples.length;i++)peak=Math.max(peak,Math.abs(samples[i]));
  if(!Number.isFinite(peak)||peak<0.00001)throw new Error("silent-audio");
  const gain=Math.pow(10,-3/20)/peak;
